			local bgBot = char:FindFirstChild(LUAOBFUSACTOR_DECRYPT_STR_0("\134\243\167\184\142\237\197\184\137\209\225", "\231\203\190\149"));
			if bgBot then
				bgBot:Destroy();
			end
		end
	end
	self:ClearGunESP();
end;
