Hub.FormatNumber = function(self, num)
	local n = tonumber(num) or 0;
	local sign = ((n < 0) and "-") or "";
	local absN = math.abs(n);
	local intPart = math.floor(absN);
	local decPart = absN - intPart;
	local formatted = tostring(intPart);
	local k;
	while true do
		formatted, k = formatted:gsub("^(-?%d+)(%d%d%d)", LUAOBFUSACTOR_DECRYPT_STR_0("\199\71\143\244\234", "\216\226\118\163\209"));
		if (k == 0) then
			break;
		end
	end
	if (decPart >= 0.01) then
		local decStr = string.format("%.2f", decPart):sub(2);
		decStr = decStr:gsub("0+$", "");
		if (decStr ~= ".") then
			return sign .. formatted .. decStr;
		end
	end
	return sign .. formatted;
end;
