local skinPropNope = {[LUAOBFUSACTOR_DECRYPT_STR_0("\121\32\253\250\87\60\251\246", "\146\56\78\158")]=true,Massless=true,[LUAOBFUSACTOR_DECRYPT_STR_0("\14\218\65\197\85\33\215\70\226\95", "\58\77\187\47\134")]=true,CanQuery=true,[LUAOBFUSACTOR_DECRYPT_STR_0("\49\52\175\51\234\59\87\22", "\126\114\85\193\103\133\78\52")]=true,[LUAOBFUSACTOR_DECRYPT_STR_0("\232\212\49\115\193\223", "\24\164\187\82")]=true,Size=true,[LUAOBFUSACTOR_DECRYPT_STR_0("\220\223\79\162\216\245", "\145\145\186\60\202")]=true,MeshSize=true,Part0=true,Part1=true,Playing=true,[LUAOBFUSACTOR_DECRYPT_STR_0("\210\217\62\1\202\213\61\3\242\216", "\100\134\176\83")]=true,IsLoaded=true,IsPlaying=true};
local skinFxClasses = {Attachment=true,Sound=true,ParticleEmitter=true,Beam=true,Trail=true,Decal=true,Texture=true,Fire=true,Smoke=true,[LUAOBFUSACTOR_DECRYPT_STR_0("\224\209\67\175\184\25\214\210", "\117\179\161\34\221\211")]=true,PointLight=true,SpotLight=true,SurfaceLight=true,Highlight=true};
