Hub.TeleportToLobby = function(self, force)
	local lp = self.Services.Players.LocalPlayer;
	local char = lp and lp.Character;
	if not char then
		return false;
	end
	local root = char:FindFirstChild(LUAOBFUSACTOR_DECRYPT_STR_0("\220\99\208\48\62\203\205\240\68\210\62\36\244\197\230\98", "\164\148\22\189\81\80\164"));
	local hum = char:FindFirstChildOfClass("Humanoid");
	if (not root or not hum) then
		return false;
	end
	if (not force and (root.Position.Y > 350)) then
		return false;
	end
	local lobby = self:GetLobby();
	local targetPart = nil;
	if lobby then
		local spawns = lobby:FindFirstChild("Spawns");
		if spawns then
			for _, child in ipairs(spawns:GetChildren()) do
				if child:IsA("BasePart") then
					targetPart = child;
					break;
				end
			end
		end
		if not targetPart then
			for _, desc in ipairs(lobby:GetDescendants()) do
				if (desc:IsA(LUAOBFUSACTOR_DECRYPT_STR_0("\129\144\118\164\41\103\120\177\129\99\186\40\69", "\23\210\224\23\211\71\43")) or (desc:IsA("BasePart") and string.find(desc.Name:lower(), "spawn"))) then
					targetPart = desc;
					break;
				end
			end
		end
		if not targetPart then
			local pad = self:GetVotePad("VotePad1") or self:GetVotePad(LUAOBFUSACTOR_DECRYPT_STR_0("\159\137\4\178\101\42\216\162", "\144\201\230\112\215\53\75\188"));
			if pad then
				if pad:IsA(LUAOBFUSACTOR_DECRYPT_STR_0("\119\196\10\239\198\164\71\209", "\197\53\165\121\138\150")) then
					targetPart = pad;
				elseif pad:IsA("Model") then
					targetPart = pad.PrimaryPart or pad:FindFirstChildWhichIsA("BasePart", true);
				end
			end
		end
	end
	if not targetPart then
		for _, desc in ipairs(self.Services.Workspace:GetDescendants()) do
			if desc:IsA("SpawnLocation") then
				targetPart = desc;
				break;
			end
		end
	end
	local targetPos = nil;
	if targetPart then
		targetPos = targetPart.Position + Vector3.new(0, 3.5, 0);
	elseif (lobby and lobby:IsA(LUAOBFUSACTOR_DECRYPT_STR_0("\192\208\221\37\225", "\64\141\191\185"))) then
		targetPos = lobby:GetPivot().Position + Vector3.new(0, 5, 0);
	end
	if not targetPos then
		return false;
	end
	pcall(function()
		hum.PlatformStand = false;
	end);
	pcall(function()
		hum.Sit = false;
	end);
	pcall(function()
		hum:ChangeState(Enum.HumanoidStateType.Running);
	end);
	pcall(function()
		root.AssemblyLinearVelocity = Vector3.zero;
	end);
	pcall(function()
		root.AssemblyAngularVelocity = Vector3.zero;
	end);
	pcall(function()
		root.Velocity = Vector3.zero;
	end);
	pcall(function()
		root.RotVelocity = Vector3.zero;
	end);
	local _, ry, _ = root.CFrame:ToOrientation();
	root.CFrame = CFrame.new(targetPos) * CFrame.Angles(0, ry, 0);
	self:RestoreCollisions();
	return true;
end;
