Hub.ScanMaps = function(self)
	local lobby = self:GetLobby();
	local pads = {"VotePad1","VotePad2","VotePad3"};
	local result = {};
	for _, padName in ipairs(pads) do
		local pad = self:GetVotePad(padName);
		local mapName = "";
		local votes = "";
		local imageId = "";
		if pad then
			local vig = pad:FindFirstChild("VoteInfoGui") or pad:FindFirstChildWhichIsA("BillboardGui", true) or pad:FindFirstChildWhichIsA(LUAOBFUSACTOR_DECRYPT_STR_0("\195\215\52\234\241\193\35\203\229\203", "\140\144\162\70"), true);
			if vig then
				local mn = vig:FindFirstChild(LUAOBFUSACTOR_DECRYPT_STR_0("\253\41\73\92\239\221\45", "\142\176\72\57\18"), true);
				if (mn and mn:IsA("TextLabel") and (mn.Text ~= "")) then
					mapName = mn.Text;
				end
				local vt = vig:FindFirstChild(LUAOBFUSACTOR_DECRYPT_STR_0("\144\62\4\33\181", "\68\198\81\112"), true);
				if (vt and vt:IsA(LUAOBFUSACTOR_DECRYPT_STR_0("\131\10\168\0\96\28\181\10\188", "\125\215\111\208\116\44")) and (vt.Text ~= "")) then
					votes = vt.Text;
				end
			end
			local mig = pad:FindFirstChild("MapInfoGui");
			if mig then
				local mi = mig:FindFirstChild("MapIcon", true);
				if (mi and mi:IsA("ImageLabel") and (mi.Image ~= "")) then
					imageId = mi.Image;
				end
			end
			local voteIcons = (lobby and lobby:FindFirstChild("VoteIcons")) or (lobby and lobby:FindFirstChild("VotePads") and lobby.VotePads:FindFirstChild("VoteIcons"));
			if voteIcons then
				local viPad = voteIcons:FindFirstChild(padName);
				if viPad then
					local img = viPad:FindFirstChildWhichIsA("ImageLabel", true);
					if (img and (img.Image ~= "")) then
						imageId = img.Image;
					end
				end
			end
		end
		if not self.Maps.Cached[padName] then
			self.Maps.Cached[padName] = {MapName=padName,Votes="0",Image=Icons.MapFallback};
		end
		if ((mapName ~= "") and (mapName ~= "Unknown Map")) then
			self.Maps.Cached[padName].MapName = mapName;
		end
		if (votes ~= "") then
			self.Maps.Cached[padName].Votes = votes;
		end
		if (imageId ~= "") then
			self.Maps.Cached[padName].Image = imageId;
		end
		table.insert(result, {PadName=padName,Pad=pad,MapName=self.Maps.Cached[padName].MapName,[LUAOBFUSACTOR_DECRYPT_STR_0("\49\72\91\246\107", "\60\103\39\47\147\24")]=self.Maps.Cached[padName].Votes,[LUAOBFUSACTOR_DECRYPT_STR_0("\197\7\246\135\211", "\46\140\106\151\224\182\147")]=self.Maps.Cached[padName].Image});
	end
	return result;
end;
Hub.TeleportToPad = function(self, padName)
	if not self:IsVotingActive() then
		return;
	end
	local pad = self:GetVotePad(padName);
	if not pad then
		return;
	end
	local targetPart = nil;
	if pad:IsA("BasePart") then
