Hub.DetectDevice = function(self)
	local uis = self.Services.UserInputService;
	local cam = self.Services.Workspace.CurrentCamera;
	local vp = (cam and cam.ViewportSize) or Vector2.new(1280, 720);
	local devType = "Desktop";
	local isTouch = uis.TouchEnabled;
	if (uis.TouchEnabled and not uis.KeyboardEnabled) then
		local minDim = math.min(vp.X, vp.Y);
		local maxDim = math.max(vp.X, vp.Y);
		if ((minDim < 540) or (maxDim < 860)) then
			devType = "Mobile";
		else
			devType = "Tablet";
		end
	elseif (uis.GamepadEnabled and not uis.KeyboardEnabled and not uis.MouseEnabled) then
		devType = "Console";
	elseif (uis.TouchEnabled and (vp.X < 920)) then
		devType = "Mobile";
	elseif (uis.TouchEnabled and (vp.X < 1200)) then
		devType = "Tablet";
	else
		devType = LUAOBFUSACTOR_DECRYPT_STR_0("\148\245\14\95\61\191\224", "\73\208\144\125\52");
	end
	self.State.Device = {Type=devType,IsTouch=isTouch,Viewport=vp,[LUAOBFUSACTOR_DECRYPT_STR_0("\3\255\167\196\197\25\95\206", "\171\74\140\234\171\167\112\51")]=(devType == LUAOBFUSACTOR_DECRYPT_STR_0("\2\1\78\86\253\168", "\205\79\110\44\63\145")),IsTablet=(devType == LUAOBFUSACTOR_DECRYPT_STR_0("\147\94\61\196\177\31", "\124\199\63\95\168\212\107\196")),IsConsole=(devType == "Console"),IsDesktop=(devType == LUAOBFUSACTOR_DECRYPT_STR_0("\34\173\64\49\176\248\153", "\147\102\200\51\90\196\151\233"))};
