Hub.WatchCharacterMorphs = function(self)
	local lp = self.Services.Players.LocalPlayer;
	if not lp then
		return;
	end
	local function setupCharWatch(char)
		if not char then
			return;
		end
		local debounce = false;
		local function triggerMorphUpdate()
			if debounce then
				return;
			end
			debounce = true;
			task.delay(0.2, function()
				debounce = false;
				if (self.Preview and self.Preview.World) then
					self:CloneLocalPlayerModel();
				end
			end);
		end
		local c1 = char.ChildAdded:Connect(triggerMorphUpdate);
		local c2 = char.ChildRemoved:Connect(triggerMorphUpdate);
		local c3 = char.DescendantAdded:Connect(function(d)
			if (d:IsA("BasePart") or d:IsA("CharacterMesh") or d:IsA("Shirt") or d:IsA("Pants") or d:IsA(LUAOBFUSACTOR_DECRYPT_STR_0("\2\163\79\84\184\93\44\178\85", "\46\67\192\44\49\203")) or d:IsA("SpecialMesh")) then
				triggerMorphUpdate();
			end
		end);
		local c4 = char.DescendantRemoving:Connect(function(d)
			if (d:IsA("BasePart") or d:IsA("CharacterMesh") or d:IsA(LUAOBFUSACTOR_DECRYPT_STR_0("\55\222\39\176\48", "\101\100\182\78\194\68\196")) or d:IsA("Pants") or d:IsA("Accessory") or d:IsA("SpecialMesh")) then
				triggerMorphUpdate();
			end
		end);
		table.insert(self.State.Connections, c1);
		table.insert(self.State.Connections, c2);
		table.insert(self.State.Connections, c3);
		table.insert(self.State.Connections, c4);
	end
	if lp.Character then
		setupCharWatch(lp.Character);
	end
	lp.CharacterAdded:Connect(function(newChar)
		setupCharWatch(newChar);
		task.wait(0.3);
		if (self.Preview and self.Preview.World) then
			self:CloneLocalPlayerModel();
		end
	end);
end;
